import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';

const packages = ['shared', 'thread', 'presenter'];
function entries(pkg) {
  const config = readFileSync(`core/${pkg}/moon.pkg`, 'utf8');
  const block = /"exports"\s*:\s*\[([^\]]+)\]/.exec(config)?.[1];
  if (!block) throw new Error(`Missing client exports: ${pkg}`);
  return [...block.matchAll(/"([a-zA-Z_][\w]*(?::[a-zA-Z_][\w]*)?)"/g)].map(
    (match) => {
      const [name, alias = name] = match[1].split(':');
      return [name, alias];
    },
  );
}

// Link the two public surfaces once, sharing MoonBit's JSON/string runtime.
// Source packages stay separate, and consumers retain their existing imports.
export function generateClient() {
  mkdirSync('core/client', { recursive: true });
  const builtin = new Set([
    'Array',
    'String',
    'Int',
    'Double',
    'Bool',
    'Unit',
    'Byte',
    'Bytes',
  ]);
  const scoped = (pkg, type) =>
    type.replace(/(?<![\w.])[A-Z]\w*\b/g, (name) =>
      builtin.has(name) ? name : `@${pkg}.${name}`,
    );
  const wrappers = packages.flatMap((pkg) =>
    entries(pkg).map(([name]) => {
      const signature = readFileSync(`core/${pkg}/pkg.generated.mbti`, 'utf8')
        .split('\n')
        .find((line) => line.startsWith(`pub fn ${name}(`));
      const match = signature?.match(/^pub fn \w+\(([^()]*)\) -> (.+)$/);
      if (!match || /\braise\b|\basync\b/.test(signature))
        throw new Error(`Expected concrete synchronous export: ${pkg}.${name}`);
      const types = match[1] ? match[1].split(', ') : [];
      const params = types.map(
        (type, index) => `p${index} : ${scoped(pkg, type)}`,
      );
      return `///|\npub fn ${name}(${params.join(', ')}) -> ${scoped(pkg, match[2])} {\n  @${pkg}.${name}(${types.map((_, index) => `p${index}`).join(', ')})\n}`;
    }),
  );
  writeFileSync(
    'core/client/client.mbt',
    '// Generated by scripts/client-bundle.mjs; do not edit.\n' +
      wrappers.join('\n\n') +
      '\n',
  );
  writeFileSync(
    'core/client/moon.pkg',
    '// Generated by scripts/client-bundle.mjs; do not edit.\n' +
      `import { ${packages.map((pkg) => `"hosi121/speakup/${pkg}"`).join(', ')} }\n` +
      'options(targets: { "client.mbt": ["js"] }, link: { "js": { "format": "esm", "exports": [\n' +
      packages
        .flatMap((pkg) => entries(pkg).map((pair) => `  "${pair.join(':')}",`))
        .join('\n') +
      '\n] } })\n',
  );
}

export function emitClientFacades() {
  for (const pkg of packages)
    writeFileSync(
      `dist/${pkg}.js`,
      '// Generated by scripts/client-bundle.mjs; do not edit.\n' +
        `export { ${entries(pkg)
          .map(([, name]) => name)
          .join(', ')} } from './client.js';\n`,
    );
  // The compiler's raw declaration cannot describe cross-package records.
  // Reuse the concrete Mbt2TS declarations of the two public source packages.
  writeFileSync(
    'dist/client.d.ts',
    '// Generated by scripts/client-bundle.mjs; do not edit.\n' +
      packages
        .map(
          (pkg) =>
            `export { ${entries(pkg)
              .map(([, name]) => name)
              .join(', ')} } from './${pkg}.js';`,
        )
        .join('\n') +
      '\n',
  );
}
